__co__ void layernorm(f32[N, M] X, f32[M] gamma, f32[M] beta, f32[N, M] Y, f32 eps) {
    f32[N] mean;
    f32[N] var;
    foreach i(0:N) {
        mean.at(i) = reduce_sum(j in 0..M) X.at(i, j) / M;
    }
    foreach i(0:N) {
        var.at(i) = reduce_sum(j in 0..M) (X.at(i, j) - mean.at(i)) * (X.at(i, j) - mean.at(i)) / M;
    }
    parallel p by N {
        foreach j(0:M) {
            Y.at(p, j) = gamma.at(j) * (X.at(p, j) - mean.at(p)) / sqrt(var.at(p) + eps) + beta.at(j);
        }
    }
}
